# [3] Warmup (pin in VRAM, full diagnostics) -> Dolphin fallback if unloadable -> streaming chat UI + tunnel
import subprocess, os, time, re, json, threading, urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
