BLOCK = ['rm -rf /','mkfs','dd if=/dev/zero of=/dev/',':(){','shutdown','reboot ',' > /dev/sda','chmod -R 777 /','history -c && rm']

def t_web_search(query, **kw):
    out = []
    for url, data in [('https://html.duckduckgo.com/html/', {'q': query}), ('https://lite.duckduckgo.com/lite/', {'q': query})]:
        try:
            r = subprocess.run(['curl','-s','-m','25','-A','Mozilla/5.0 (X11; Linux x86_64)','-d','q=' + query.replace(' ','+'), url], capture_output=True, text=True)
            h = r.stdout or ''
            for m in re.finditer(r'<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>', h, re.S)[:0] or re.findall(r'<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>', h, re.S)[:8]:
                u, title = m[0], re.sub('<[^>]+>','',m[1])
                if 'uddg=' in u:
                    u = urllib.parse.unquote(u.split('uddg=')[1].split('&')[0])
                snip = ''
                sm = re.search('result__snippet[^>]*>(.*?)</a>', h[h.find(m[1]):h.find(m[1])+3000], re.S)
                if sm: snip = re.sub('<[^>]+>','',sm.group(1))[:220]
                out.append('* ' + htmlmod.unescape(title.strip()) + ' :: ' + u + (chr(10)+'  ' + htmlmod.unescape(snip.strip()) if snip else ''))
            if out: break
        except Exception as e:
            continue
    if not out:
        try:
            r = subprocess.run(['curl','-s','-m','20','https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=' + urllib.parse.quote(query) + '&format=json&srlimit=5'], capture_output=True, text=True)
            j = json.loads(r.stdout)
            for it in j.get('query',{}).get('search',[]):
                out.append('* ' + it['title'] + ' :: https://en.wikipedia.org/wiki/' + it['title'].replace(' ','_') + chr(10) + '  ' + re.sub('<[^>]+>','',it['snippet'])[:200])
        except Exception: pass
    return (chr(10).join(out) or 'no results')[:4000]

def _readable(h):
    h = re.sub(r'<(script|style|noscript)[^>]*>.*?</\1>','',h,flags=re.S|re.I)
    t = re.sub(r'<[^>]+>',' ',h)
    t = htmlmod.unescape(re.sub(r'\s+',' ',t))
    return t.strip()

def t_fetch_page(url, **kw):
    if not url.startswith('http'): url = 'https://' + url
    r = subprocess.run(['curl','-sL','-m','40','-A','Mozilla/5.0 (X11; Linux x86_64)',url], capture_output=True, text=True)
    txt = _readable(r.stdout or '')
    return ('HTTP-fetched ' + url + chr(10) + txt[:12000]) if txt else ('fetch failed or empty: ' + url)

def t_crawl_site(url, max_pages=6, **kw):
    if not url.startswith('http'): url = 'https://' + url
    max_pages = min(max(1, max_pages or 6), 10)
    seen, todo, done, texts = {url}, [url], [], []
    base = re.match(r'https?://[^/]+', url).group(0)
    while todo and len(done) < max_pages:
        u = todo.pop(0)
        try:
            r = subprocess.run(['curl','-sL','-m','30','-A','Mozilla/5.0',u], capture_output=True, text=True)
            h = r.stdout or ''
            done.append(u)
            tx = _readable(h)
            if tx: texts.append('## ' + u + chr(10) + tx[:4000])
            for lm in re.findall(r'href="(/[^"]{1,120}|' + re.escape(base) + r'[^"]{1,120})"', h)[:40]:
                lu = lm if lm.startswith('http') else base + lm
                if lu not in seen and '.' not in lm.split('/')[-1][:6]:
                    seen.add(lu); todo.append(lu)
        except Exception: continue
    return (chr(10)+chr(10)).join(texts)[:16000] or 'crawl empty'

def t_run_command(command, timeout=60, **kw):
    for b in BLOCK:
        if b in command: return 'BLOCKED for safety: ' + b
    try:
        r = subprocess.run(command, shell=True, capture_output=True, text=True, timeout=min(max(5,int(timeout or 60)),150), cwd='/kaggle/working')
        o = ((r.stdout or '') + (chr(10)+'[stderr] ' + r.stderr if r.stderr else ''))[:6000]
        return 'exit=' + str(r.returncode) + chr(10) + (o or '(no output)')
    except subprocess.TimeoutExpired:
        return 'TIMED OUT after ' + str(timeout) + 's'
    except Exception as e:
        return 'error: ' + str(e)

GEN_DIR = '/kaggle/working/generated'

def _safe_name(fn, ext):
    fn = re.sub(r'[^A-Za-z0-9_.-]', '_', str(fn or ''))[:60] or (ext + '_' + str(int(time.time())))
    if not fn.lower().endswith('.' + ext): fn += '.' + ext
    return fn

def t_generate_image(prompt, filename=None, **kw):
    os.makedirs(GEN_DIR, exist_ok=True)
    name = _safe_name(filename, 'jpg')
    p = GEN_DIR + '/' + name
    u = 'https://image.pollinations.ai/prompt/' + urllib.parse.quote(prompt[:600]) + '?width=1024&height=1024&nologo=true'
    r = subprocess.run(['curl', '-sL', '-m', '150', '-o', p, u], capture_output=True)
    try:
        head = open(p, 'rb').read(4)
    except Exception:
        return 'image generation failed: no file written'
    if head[:2] not in (b'\xff\xd8', b'\x89P'):
        return 'image generation failed: bad file header (try again)'
    n = os.path.getsize(p)
    if not url:
        return 'IMAGE SAVED but tunnel url unknown yet: ' + name + ' (' + str(n) + ' bytes)'
    return 'IMAGE READY: ' + url + '/files/' + name + ' (' + str(n) + ' bytes) - give the user this URL and they can view it in the browser.'

def t_generate_voice(text, voice='en_US-lessac-medium', **kw):
    os.makedirs(GEN_DIR, exist_ok=True)
    try:
        if subprocess.run(['python3', '-c', 'import piper'], capture_output=True).returncode != 0:
            subprocess.run(['pip', 'install', '-q', 'piper-tts'], capture_output=True, timeout=140)
    except Exception:
        return 'piper install timed out (slow network) - ask the user to retry in a minute'
    marker = GEN_DIR + '/.voice_' + voice.replace('/', '_')
    if not os.path.exists(marker):
        try:
            d = subprocess.run(['python3', '-m', 'piper.download_voices', voice], capture_output=True, text=True, timeout=140)
        except Exception:
            return 'voice download timed out - ask the user to retry in a minute'
        if d.returncode != 0:
            return 'voice download failed: ' + ((d.stdout or '') + (d.stderr or ''))[:200]
        open(marker, 'w').write('ok')
    name = _safe_name(None, 'wav')
    p = GEN_DIR + '/' + name
    try:
        r = subprocess.run(['piper', '--model', voice, '--output_file', p], input=str(text)[:1200].encode(), capture_output=True, timeout=120)
    except Exception:
        return 'TTS timed out - ask the user to retry'
    if r.returncode != 0 or not os.path.exists(p):
        return 'TTS failed: ' + (r.stderr or b'').decode(errors='ignore')[:200]
    n = os.path.getsize(p)
    if not url:
        return 'AUDIO SAVED but tunnel url unknown yet: ' + name + ' (' + str(n) + ' bytes)'
    return 'AUDIO READY: ' + url + '/files/' + name + ' (' + str(n) + ' bytes) - give the user this URL so they can play it.'

EXEC = {'web_search': t_web_search, 'fetch_page': t_fetch_page, 'crawl_site': t_crawl_site, 'run_command': t_run_command, 'generate_image': t_generate_image, 'generate_voice': t_generate_voice}

