function scroll(){log.scrollTop = log.scrollHeight}
function media(t){
  var parts = t.split(/(https?:\/\/[^\s)]+)/);
  var out = '';
  for (var i=0;i<parts.length;i++){
    var p = parts[i];
    if (/^https?:\/\//.test(p) && /\.(wav|jpg|jpeg|png)(\?.*)?$/i.test(p)) {
