function send(){
  var q = inp.value.trim();
  if(!q || go.disabled) return;
  inp.value=''; hist.push({role:'user', content:q});
  var um=document.createElement('div'); um.className='m u'; um.textContent=q; log.appendChild(um); scroll();
  var am=document.createElement('div'); am.className='m a'; log.appendChild(am);
  var tm=null, txt='', th='', st=document.createElement('div'); st.className='st'; st.textContent='thinking...'; log.appendChild(st);
  go.disabled=true;
  fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:MODEL,messages:hist,stream:true})}).then(function(r){
    var reader=r.body.getReader(), dec=new TextDecoder(), buf='';
    function pump(){
      return reader.read().then(function(res){
