        buf += dec.decode(res.value,{stream:true});
        var lines = buf.split('\n'); buf = lines.pop();
        for(var i=0;i<lines.length;i++){ handle(lines[i]); }
        scroll();
        return pump();
      });
    }
    return pump();
  }).catch(function(){ finish(); });
  function handle(line){
    line=line.trim(); if(!line) return;
    var d; try{ d=JSON.parse(line); }catch(e){ return; }
    var m=d.message||{};
    if(m.thinking){ th+=m.thinking; if(!tm){ tm=document.createElement('div'); tm.className='t'; log.insertBefore(tm, st); } tm.textContent='🛠 '+m.thinking.replace(/[⚙⏳↳]️?/g,function(x){return x;}); }
