PAGE = PAGE_HTML.encode()

class H(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    def log_message(self, *a): pass
    def _cors(self):
        # FIX (audit C5): no CORS. The engine is only ever called
        # server-to-server by Aether; a wildcard ACAO let any web page drive
        # the agent from a visitor's browser.
        pass
    def do_OPTIONS(self):
        self.send_response(204); self._cors()
        self.send_header('Access-Control-Allow-Methods','GET, POST, OPTIONS'); self.send_header('Access-Control-Allow-Headers','Content-Type')
        self.send_header('Access-Control-Max-Age','86400'); self.send_header('Content-Length','0'); self.end_headers()
    def do_GET(self):
        if self.path in ('/','/index.html','/chat'):
            self.send_response(200); self.send_header('Content-Type','text/html'); self.send_header('Content-Length', str(len(PAGE))); self._cors(); self.end_headers(); self.wfile.write(PAGE)
        elif self.path == '/files/list':
            try:
                items = [{'name': f, 'size': os.path.getsize(GEN_DIR + '/' + f)} for f in sorted(os.listdir(GEN_DIR)) if not f.startswith('.')]
            except Exception:
                items = []
            data = json.dumps(items).encode()
            self.send_response(200); self.send_header('Content-Type', 'application/json'); self.send_header('Content-Length', str(len(data))); self._cors(); self.end_headers(); self.wfile.write(data)
        elif self.path.startswith('/files/'):
            fn = self.path[len('/files/'):]
            if not re.fullmatch(r'[A-Za-z0-9_.-]+', fn) or '..' in fn:
                self.send_response(400); self.send_header('Content-Length', '0'); self.end_headers(); return
            fp = GEN_DIR + '/' + fn
            if not os.path.exists(fp):
                self.send_response(404); self.send_header('Content-Length', '0'); self._cors(); self.end_headers(); return
            ext = fn.rsplit('.', 1)[-1].lower()
            ctype = {'wav': 'audio/wav', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png'}.get(ext, 'application/octet-stream')
            data = open(fp, 'rb').read()
            self.send_response(200); self.send_header('Content-Type', ctype); self.send_header('Content-Length', str(len(data))); self._cors(); self.end_headers(); self.wfile.write(data)
        else:
            try:
                resp = urllib.request.urlopen('http://127.0.0.1:11434' + self.path, timeout=60)
                data = resp.read()
                self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length', str(len(data))); self._cors(); self.end_headers(); self.wfile.write(data)
            except Exception as ex:
                msg = str(ex).encode(); self.send_response(502); self.send_header('Content-Length', str(len(msg))); self._cors(); self.end_headers(); self.wfile.write(msg)
    def _read_body(self):
        # FIX (501 bug): this handler is HTTP/1.1, so sockets are keep-alive.
        # Answering WITHOUT consuming the request body leaves those bytes in the
        # socket, and the next request parsed off that same connection reads the
        # leftover JSON as a request line -> "Unsupported method" -> 501. That is
        # exactly the 403/501 alternation seen on the live engine. So the body is
        # read ONCE, here, before any branch can return early.
        try:
            n = int(self.headers.get('Content-Length') or 0)
        except Exception:
            n = 0
        try:
            return self.rfile.read(n) if n > 0 else b''
        except Exception:
            self.close_connection = True
            return b''
    def do_POST(self):
        body = self._read_body()
        # FIX (audit C5): every POST is authenticated. Previously only /off
        # checked the key, so anyone who learned the tunnel URL could drive
        # /api/chat - and its run_command tool - or the raw ollama proxy.
        if self.headers.get('X-Engine-Key') != OFF_KEY:
            msg = b'{"status":"forbidden"}'
            self.send_response(403); self.send_header('Content-Type','application/json'); self.send_header('Content-Length', str(len(msg))); self.end_headers(); self.wfile.write(msg); self.wfile.flush()
            return
        if self.path == '/off':
            # Key already checked above; the old second check here was dead code.
            try:
                msg = b'{"status":"shutting down"}'
                self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length', str(len(msg))); self.end_headers(); self.wfile.write(msg)
                # wbufsize == 0, so wfile writes straight to the socket; this
                # flush is a no-op kept for symmetry. (An earlier comment here
                # claimed the body could be lost without it -- measured false.)
                self.wfile.flush()
            except Exception:
                pass
            notify('ENGINE OFF via UI - quota saved')
            print('ENGINE OFF requested - shutting down now', flush=True)
            threading.Thread(target=lambda: (time.sleep(0.5), os._exit(0))).start()
            return
        if self.path != '/api/chat':
            try:
                rq = urllib.request.Request('http://127.0.0.1:11434' + self.path, data=body, method='POST'); rq.add_header('Content-Type','application/json')
                resp = urllib.request.urlopen(rq, timeout=300); data = resp.read()
                self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length', str(len(data))); self._cors(); self.end_headers(); self.wfile.write(data)
            except Exception as ex:
                msg = str(ex).encode(); self.send_response(502); self.send_header('Content-Length', str(len(msg))); self._cors(); self.end_headers(); self.wfile.write(msg)
            return
        LAST_HIT['t'] = time.time()
        try:
            payload = json.loads(body or b'{}')
        except Exception:
            payload = {}
        self._sent = False
        try:
            agent_stream(self, payload)
        except IOError:
            pass
        except Exception as ex:
            # FIX: if agent_stream already wrote a status line, sending another
            # one would land inside the response body and desynchronise the
            # keep-alive socket - the same class of bug as the 403 above.
            if getattr(self, '_sent', False):
                pass
            else:
